// Compiles the production warm/cold white scaling (BusDigital::setPixelColor() helper) with a host compiler
// and runs test/cct/cases.cpp against it.
const assert = require('node:assert/strict');
const { it } = require('node:test');
const fs = require('node:fs');
const path = require('node:path');
const os = require('node:os');
const { spawnSync } = require('node:child_process');

// returns the complete definition that starts at signature, up to its closing brace
function extract(source, signature) {
  const start = source.indexOf(signature);
  assert.ok(start >= 0, 'Missing production definition ' + signature);
  const brace = source.indexOf('{', start);
  let depth = 0;
  for (let end = brace; end < source.length; end++) {
    if (source[end] === '{') depth++;
    if (source[end] === '}' && --depth === 0) return source.slice(start, end + 1);
  }
  throw new Error('Unclosed production definition ' + signature);
}

it('warm and cold white keep their mix when dimmed', t => {
  const compiler = process.env.CXX || 'g++';
  const probe = spawnSync(compiler, ['--version'], { encoding: 'utf8' });
  if (probe.error?.code === 'ENOENT') return t.skip('Host C++ compiler is unavailable');
  assert.equal(probe.status, 0, probe.stderr);
  const root = path.resolve(__dirname, '..');
  const read = name => fs.readFileSync(path.join(root, 'wled00', name), 'utf8');
  const colors = read('colors.h'), bus = read('bus_manager.cpp');
  const macros = colors.split('\n').filter(line => /^#define (?:RGBW32|R|G|B|W)\(/.test(line)).join('\n');
  assert.equal(macros.split('\n').length, 5, 'Missing color channel macros');
  // the call site must scale the pair before the color is faded, as the helper compares against the unscaled color
  const setPixel = extract(bus, 'void BusDigital::setPixelColor(');
  const scaleAt = setPixel.indexOf('scaleCct(cct, bri,'), fadeAt = setPixel.indexOf('color_fade(c, bri, true)');
  assert.ok(scaleAt >= 0 && fadeAt > scaleAt, 'scaleCct() must run before color_fade()');
  const source = fs.readFileSync(path.join(root, 'test/cct/cases.cpp'), 'utf8')
    .replace('/* COLOR_MACROS */', macros)
    .replace('/* CCT_PIXEL */', extract(colors, 'struct CctPixel') + ';')
    .replace('/* SCALE_CCT */', extract(bus, 'static inline void scaleCct('));
  const temp = fs.mkdtempSync(path.join(os.tmpdir(), 'wled-cct-'));
  try {
    const cpp = path.join(temp, 'cct.cpp'), binary = path.join(temp, 'cct-test');
    fs.writeFileSync(cpp, source);
    const build = spawnSync(compiler, ['-std=c++17', '-O0', '-Wall', '-Wextra', '-fsanitize=undefined', cpp, '-o', binary], { encoding: 'utf8' });
    assert.equal(build.status, 0, build.stdout + '\n' + build.stderr);
    const run = spawnSync(binary, [], { encoding: 'utf8' });
    t.diagnostic(run.stdout.trim().split('\n').at(-1));
    assert.equal(run.status, 0, run.stdout + '\n' + run.stderr);
  } finally {
    fs.rmSync(temp, { recursive: true, force: true });
  }
});
